// Catalogue state lives in the URL and memory; no buyer information is stored here.
let catalogueState={q:'',category:'',facets:{},sort:'default'};
let catalogueScroll=0,catalogueReturnFocus='',renderedRoute='',refreshCatalogue=null,catalogueHasPosition=false;
const copyFilterState=s=>({...s,facets:{...s.facets}});
const emptyFilters=(sort='default')=>({q:'',category:'',facets:{},sort});
function facetValues(category,key){return [...new Set(products.filter(p=>p.category===category).map(p=>p.specs[key]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}))}
function usefulFacetKeys(category){return (facetKeys[category]||[]).filter(k=>facetValues(category,k).length>1)}
function normalizeSearch(text){return String(text).normalize('NFKD').toLowerCase().replace(/(\d)\s*(gsm|mm|cm|ml)\b/g,'$1$2').replace(/[^a-z0-9]+/g,' ').trim()}
function queryTokens(query){let q=normalizeSearch(query);const aliases=[[/\b(?:printer|printing|photocopier|photocopy|copy) paper\b/g,'paper'],[/\b(?:ball pen|ball pens|ballpoint pen)\b/g,'ballpoint'],[/\b(?:colouring|coloring|color) pencils\b/g,'coloured pencils'],[/\bexercise books?\b/g,'exercise book']];for(const [pattern,to]of aliases)q=q.replace(pattern,to);return q.split(' ').filter(Boolean)}
function searchMatches(p,query){const words=normalizeSearch([p.name,p.summary,p.unit,p.brand,...Object.values(p.specs)].join(' ')).split(' ');return queryTokens(query).every(token=>words.some(word=>{if(/\d/.test(token))return word===token;const stem=t=>t.length>3?t.replace(/s$/,''):t;return stem(word).startsWith(stem(token))}))}
function matchingProducts(s,ignoreFacet='',ignoreCategory=false){return products.filter(p=>searchMatches(p,s.q)&&(!s.category||ignoreCategory||p.category===s.category)&&Object.entries(s.facets).every(([key,value])=>key===ignoreFacet||ignoreCategory||p.specs[key]===value))}
function cleanFilterState(s){const category=categories.some(c=>c[2]===s.category)?s.category:'';const keys=usefulFacetKeys(category);return {q:String(s.q||'').trim().slice(0,160),category,sort:s.sort==='name'?'name':'default',facets:Object.fromEntries(Object.entries(s.facets||{}).filter(([k,v])=>keys.includes(k)&&facetValues(category,k).includes(v)))}}
function readCatalogueState(){const raw=location.hash.split('?')[1];if(raw===undefined)return cleanFilterState(history.state?.lepetseFilters||catalogueState);const params=new URLSearchParams(raw);return cleanFilterState({q:params.get('q')||'',category:params.get('category')||'',sort:params.get('sort')||'default',facets:Object.fromEntries([...params].filter(([k])=>k.startsWith('f.')).map(([k,v])=>[k.slice(2),v]))})}
function catalogueHref(s=catalogueState){const p=new URLSearchParams();if(s.q)p.set('q',s.q);if(s.category)p.set('category',s.category);if(s.sort!=='default')p.set('sort',s.sort);for(const [k,v]of Object.entries(s.facets).sort())p.set('f.'+k,v);return '#stationery'+(p.size?'?'+p.toString():'')}
function saveFilterUrl(){const hash=catalogueHref();if(location.hash!==hash)history.pushState({lepetseFilters:copyFilterState(catalogueState)},'',hash)}
function facetLabel(k){return {Weight:'Paper weight',Pages:'Page count'}[k]||k}
function facetMarkup(state,prefix){return usefulFacetKeys(state.category).map((key,i)=>{const options=facetValues(state.category,key).map(value=>{const count=matchingProducts({...state,facets:{...state.facets,[key]:value}},'').length;const selected=state.facets[key]===value;return `<option value="${esc(value)}" ${selected?'selected':''} ${count===0&&!selected?'disabled':''}>${esc(value)} (${count})</option>`}).join('');return `<div class="filter-field"><label for="${prefix}-facet-${i}">${facetLabel(key)}</label><select id="${prefix}-facet-${i}" data-spec-filter="${esc(key)}"><option value="">All</option>${options}</select></div>`}).join('')}
function categoryCount(state,category){return products.filter(p=>searchMatches(p,state.q)&&(!category||p.category===category)).length}
function desktopFilters(state){const all=categoryCount(state,'');return `<fieldset class="category-choices"><legend>Categories</legend>${[['','All products'],...categories.map(c=>[c[2],c[0]])].map(([id,label],i)=>{const count=categoryCount(state,id);return `<label for="category-${i}" class="category-choice ${state.category===id?'selected':''}"><input id="category-${i}" type="radio" name="category" value="${id}" data-category-choice ${state.category===id?'checked':''} ${!count&&state.category!==id?'disabled':''}><span>${label}</span><small>${count}</small></label>`}).join('')}</fieldset>${usefulFacetKeys(state.category).length?`<fieldset class="specification-choices"><legend>Specifications</legend>${facetMarkup(state,'desktop')}</fieldset>`:''}<a class="catalogue-upload-link" href="#upload">Upload your list</a>`}
function filterChips(state){const chips=[];if(state.q)chips.push(['q','Search: '+state.q]);if(state.category)chips.push(['category',categories.find(c=>c[2]===state.category)[0]]);for(const [k,v]of Object.entries(state.facets))chips.push(['facet:'+k,facetLabel(k)+': '+v]);return chips.map(([key,label])=>`<button class="filter-chip" data-remove-filter="${esc(key)}" aria-label="Remove ${esc(label)}">${esc(label)} <span aria-hidden="true">×</span></button>`).join('')}
function filterCount(s){return Number(!!s.category)+Object.keys(s.facets).length}
function catalogue(){return `<section class="catalogue-heading catalogue-heading-compact"><div class="wrap"><span class="eyebrow">Stationery catalogue</span><h1 tabindex="-1">Office and school stationery</h1><p>Browse products, choose quantities and add items to your quote basket.</p></div></section><section class="catalogue-section"><div class="wrap catalogue-layout advanced-catalogue"><aside class="catalogue-filters advanced-filters" aria-label="Filter products" id="desktop-filters"></aside><div><div class="catalogue-tools catalogue-tools-compact"><span>Prices are provided by quotation.</span><div><label for="catalogue-sort">Sort by</label><select id="catalogue-sort"><option value="default">Featured order</option><option value="name">Name A–Z</option></select></div></div><div class="mobile-filter-bar"><button class="btn outline" id="open-filters" aria-haspopup="dialog">Filters</button><span id="mobile-result-count"></span><a href="#basket">Basket <span class="basket-count"></span></a></div><div class="catalogue-results-line" id="catalogue-results-start"><span id="result-count" role="status" aria-live="polite" aria-atomic="true" tabindex="-1"></span><button class="clear-filters" id="reset-filters">Clear all</button></div><div id="active-filters" class="active-filters" aria-label="Active filters"></div><div class="product-grid" id="product-results"></div></div></div></section>`}
function bindCatalogue(){initCatalogueScroll();catalogueState=readCatalogueState();history.replaceState({lepetseFilters:copyFilterState(catalogueState)},'',location.href);$('#global-search').value=catalogueState.q;$('#catalogue-sort').value=catalogueState.sort;
function update(next,{focusId='',chipFocus=false}={}){catalogueState=cleanFilterState(next);saveFilterUrl();draw();scrollCatalogueResults();if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});if(chipFocus)($('#active-filters button')||$('#result-count')).focus()}
function draw(){let shown=matchingProducts(catalogueState);if(catalogueState.sort==='name')shown.sort((a,b)=>a.name.localeCompare(b.name));$('#desktop-filters').innerHTML=desktopFilters(catalogueState);$('#active-filters').innerHTML=filterChips(catalogueState);$('#reset-filters').hidden=!catalogueState.q&&!catalogueState.category&&!Object.keys(catalogueState.facets).length;$('#result-count').textContent=`${shown.length} product${shown.length===1?'':'s'}${catalogueState.q?' matching “'+catalogueState.q+'”':''}`;$('#mobile-result-count').textContent=`${shown.length} products`;$('#open-filters').textContent=`Filters${filterCount(catalogueState)?' ('+filterCount(catalogueState)+')':''}`;$('#product-results').innerHTML=shown.map(productCard).join('')||`<div class="empty"><h2>No matching products</h2><p>Remove a filter above, clear all selections, or upload your list.</p><button class="btn outline" id="empty-reset">Clear all</button></div>`;$('#global-search').value=catalogueState.q;$('#catalogue-sort').value=catalogueState.sort;
main.querySelectorAll('[data-category-choice]').forEach(e=>e.onchange=()=>update({...catalogueState,category:e.value,facets:{}},{focusId:e.id}));main.querySelectorAll('[data-spec-filter]').forEach(e=>e.onchange=()=>{const next=copyFilterState(catalogueState);if(e.value)next.facets[e.dataset.specFilter]=e.value;else delete next.facets[e.dataset.specFilter];update(next,{focusId:e.id})});main.querySelectorAll('[data-remove-filter]').forEach(e=>e.onclick=()=>{const next=copyFilterState(catalogueState);const key=e.dataset.removeFilter;if(key==='q')next.q='';else if(key==='category'){next.category='';next.facets={}}else delete next.facets[key.slice(6)];update(next,{chipFocus:true})});$('#empty-reset')?.addEventListener('click',()=>update(emptyFilters(catalogueState.sort),{chipFocus:true}));bindProducts();updateCount()}
$('#reset-filters').onclick=()=>update(emptyFilters(catalogueState.sort),{chipFocus:true});$('#catalogue-sort').onchange=e=>update({...catalogueState,sort:e.target.value},{focusId:'catalogue-sort'});$('#open-filters').onclick=()=>openMobileFilters(update);refreshCatalogue=q=>update({...catalogueState,q});draw()}
function openMobileFilters(onApply){const dialog=$('#filter-dialog');let draft=copyFilterState(catalogueState);function draw(focusId=''){dialog.innerHTML=`<div class="filter-dialog-header"><h2 id="filter-dialog-title">Filter products</h2><button type="button" id="close-filters" aria-label="Close filters">×</button></div><div class="filter-dialog-body">${draft.q?`<p class="help">Search: ${esc(draft.q)}</p>`:''}<div class="filter-field"><label for="mobile-category">Category</label><select id="mobile-category">${[['','All products'],...categories.map(c=>[c[2],c[0]])].map(([id,label])=>{const count=categoryCount(draft,id);return `<option value="${id}" ${draft.category===id?'selected':''} ${count===0&&draft.category!==id?'disabled':''}>${label} (${count})</option>`}).join('')}</select></div>${facetMarkup(draft,'mobile')}</div><div class="filter-dialog-footer"><button class="clear-filters" id="clear-draft">Clear all</button><button class="btn dark" id="apply-filters">Show ${matchingProducts(draft).length} product${matchingProducts(draft).length===1?'':'s'}</button></div>`;$('#close-filters').onclick=()=>dialog.close();$('#mobile-category').onchange=e=>{draft.category=e.target.value;draft.facets={};draw('mobile-category')};dialog.querySelectorAll('[data-spec-filter]').forEach(e=>e.onchange=()=>{if(e.value)draft.facets[e.dataset.specFilter]=e.value;else delete draft.facets[e.dataset.specFilter];draw(e.id)});$('#clear-draft').onclick=()=>{draft=emptyFilters(draft.sort);draw('mobile-category')};$('#apply-filters').onclick=()=>{dialog.close();onApply(draft);$('#open-filters').focus({preventScroll:true})};if(focusId)document.getElementById(focusId)?.focus()};draw();dialog.showModal();$('#mobile-category').focus()}
function navigateCatalogueSearch(q){if(renderedRoute==='stationery'&&refreshCatalogue){refreshCatalogue(q);return}catalogueState=cleanFilterState({...emptyFilters(),q});location.hash=catalogueHref(catalogueState)}
function beforeCatalogueNavigation(){const next=(location.hash.slice(1)||'home').split('?')[0];if(renderedRoute==='stationery'&&next!=='stationery'){catalogueHasPosition=true;catalogueScroll=window.scrollY;catalogueReturnFocus=document.activeElement?.getAttribute('href')||''}}
function finishCatalogueNavigation(route){const returning=route==='stationery'&&renderedRoute!=='stationery'&&catalogueHasPosition;renderedRoute=route;document.body.classList.toggle('catalogue-active',route==='stationery');if(returning){requestAnimationFrame(()=>{const link=[...main.querySelectorAll('a')].find(a=>a.getAttribute('href')===catalogueReturnFocus);link?.focus({preventScroll:true});window.scrollTo(0,catalogueScroll)})}else if(route!=='stationery')window.scrollTo(0,0)}

function scrollCatalogueResults(){const anchor=document.getElementById('catalogue-results-start');if(!anchor)return;const bar=document.querySelector('.mobile-filter-bar');const headerHeight=document.querySelector('header')?.offsetHeight||0;const offset=headerHeight+(matchMedia('(max-width:800px)').matches?(bar?.offsetHeight||0)+12:20);const top=anchor.getBoundingClientRect().top;if(top<offset)window.scrollTo({top:Math.max(0,window.scrollY+top-offset),behavior:'instant'})}
let catalogueTopButton;function initCatalogueScroll(){if(catalogueTopButton)return;catalogueTopButton=document.createElement('button');catalogueTopButton.className='catalogue-back-top';catalogueTopButton.textContent='↑ Back to top';catalogueTopButton.hidden=true;catalogueTopButton.onclick=()=>{window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('.catalogue-heading h1')?.focus({preventScroll:true})};document.body.append(catalogueTopButton);function updateCatalogueTop(){if(!catalogueTopButton)return;catalogueTopButton.hidden=renderedRoute!=='stationery'||window.scrollY<700}window.addEventListener('scroll',updateCatalogueTop,{passive:true});window.addEventListener('hashchange',updateCatalogueTop);}
